function validate(input) {
  const [{ emails = [], texts = [] }] = input;
  const stamp = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/;
  const ids = new Set(), users = new Set(), textIds = new Set(), verified = new Set();
  for (const [id, user, signup] of emails) {
    if (id === null || user === null) return 'Every email needs an email_id and a user_id.';
    if (ids.has(id)) return `email_id ${id} appears twice in emails.`;
    if (users.has(user)) return `user_id ${user} signs up twice.`;
    if (typeof signup !== 'string' || !stamp.test(signup)) return `Email ${id} needs a signup_date like '2022-06-14 09:30:00'.`;
    ids.add(id); users.add(user);
  }
  for (const [id, email, action, when] of texts) {
    if (id === null) return 'Every text needs a text_id.';
    if (textIds.has(id)) return `text_id ${id} appears twice in texts.`;
    textIds.add(id);
    if (!ids.has(email)) return `Text ${id} names email ${email}, which is not in emails.`;
    if (action !== 'Verified' && action !== 'Not Verified') return `Text ${id} has signup_action ${action}; use 'Verified' or 'Not Verified'.`;
    if (typeof when !== 'string' || !stamp.test(when)) return `Text ${id} needs an action_date like '2022-06-15 08:30:00'.`;
    if (action === 'Verified') {
      if (verified.has(email)) return `Email ${email} has two 'Verified' texts.`;
      verified.add(email);
    }
  }
  return null;
}

