function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const pad = n => String(n).padStart(2, '0');
  const format = ms => {
    const d = new Date(ms);
    return `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
  };
  const DAY = 86400000, start = Date.UTC(2022, 0, 1);
  // Small cases sign up near month and year ends so boundaries show up often.
  const edges = [Date.UTC(2022, 5, 30), Date.UTC(2022, 11, 31), Date.UTC(2024, 1, 28), Date.UTC(2023, 1, 28), Date.UTC(2022, 6, 9)];
  const count = small ? Math.floor(rand() * 8) : 1500;
  const emails = [], texts = [];
  const users = new Set();
  for (let i = 0; i < count; i++) {
    const emailId = small ? 100 + i * 7 + Math.floor(rand() * 7) : 100 + i * 3 + Math.floor(rand() * 3);
    let user;
    do user = 1000 + Math.floor(rand() * (small ? 40 : 9000)); while (users.has(user));
    users.add(user);
    const day = small && rand() < 0.5 ? pick(edges) : start + Math.floor(rand() * 1000) * DAY;
    // Times near midnight make "next calendar day" differ from "within 24 hours".
    const minute = small ? pick([5, 30, 600, 1200, 1430]) : Math.floor(rand() * 1440);
    const signup = day + minute * 60000 + Math.floor(rand() * 60) * 1000;
    emails.push([emailId, user, format(signup)]);
    // Each email gets up to two texts: possibly a failed attempt, then possibly a success.
    const later = () => format(day + pick([0, 1, 1, 1, 2, 3]) * DAY + Math.floor(rand() * 1440) * 60000);
    if (rand() < 0.35) texts.push([0, emailId, 'Not Verified', later()]);
    if (rand() < 0.75) texts.push([0, emailId, 'Verified', later()]);
  }
  if (small && texts.length > 8) texts.length = 8;
  // Shuffle the rows, then number the texts.
  for (const rows of [emails, texts]) for (let i = rows.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [rows[i], rows[j]] = [rows[j], rows[i]];
  }
  texts.forEach((row, i) => { row[0] = i + 1; });
  return [{ emails, texts }];
}
